package com.mentalmadad.service.impl;
import com.mentalmadad.dto.response.*; import com.mentalmadad.entity.Doctor; import com.mentalmadad.exception.ResourceNotFoundException; import com.mentalmadad.repository.DoctorRepository; import com.mentalmadad.service.DoctorService; import org.springframework.data.domain.*; import org.springframework.stereotype.Service;
@Service public class DoctorServiceImpl implements DoctorService { private final DoctorRepository repo; public DoctorServiceImpl(DoctorRepository repo){this.repo=repo;} private DoctorResponse map(Doctor d){return DoctorResponse.builder().id(d.getId()).name(d.getUser().getFirstName()+" "+d.getUser().getLastName()).specialization(d.getSpecialization()).licenseNumber(d.getLicenseNumber()).yearsOfExperience(d.getYearsOfExperience()).consultationFee(d.getConsultationFee()).rating(d.getRating()).reviewCount(d.getReviewCount()).availableForChat(d.isAvailableForChat()).availableForVideo(d.isAvailableForVideo()).availableInPerson(d.isAvailableInPerson()).build();} public Page<DoctorResponse> list(String s,String n,int p,int z){ PageRequest page=PageRequest.of(p,z); if ((s==null || s.isBlank()) && (n==null || n.isBlank())) return repo.findAll(page).map(this::map); return repo.search(s,n,page).map(this::map);} public DoctorDetailResponse get(Long id){Doctor d=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Doctor","id",id)); return new DoctorDetailResponse(map(d),d.getAbout());} }
